INSERT INTO public.world_record_global(id_user,id_level,id_record,date_created,date_updated) SELECT id_user,$1,id,clock_timestamp(),clock_timestamp() FROM eligible_record_winners ORDER BY time,date_created,id LIMIT 1 ON CONFLICT(id_level) DO UPDATE SET id_user=excluded.id_user,id_record=excluded.id_record,date_updated=clock_timestamp() WHERE ROW(world_record_global.id_user,world_record_global.id_record) IS DISTINCT FROM ROW(excluded.id_user,excluded.id_record)
